#ifndef LLVM_STM8_INST_PRINTER_H_INCLUDED
#define LLVM_STM8_INST_PRINTER_H_INCLUDED

#include "llvm/MC/MCInstPrinter.h"

namespace llvm {

class STM8InstPrinter : public MCInstPrinter {
public:
  STM8InstPrinter(const MCAsmInfo &MAI, const MCInstrInfo &MII,
                  const MCRegisterInfo &MRI);

  void printInst(const MCInst *MI, uint64_t Address, StringRef Annot,
                 const MCSubtargetInfo &STI, raw_ostream &O) override;

  // Autogenerated by TableGen.
  std::pair<const char *, uint64_t> getMnemonic(const MCInst *MI) override;

private:
  static const char *getRegisterName(MCRegister Reg);

  void printOperand(const MCInst *MI, unsigned OpNo, raw_ostream &O);

  void printInstruction(const MCInst *MI, uint64_t Address, raw_ostream &O);
  bool printAliasInstr(const MCInst *MI, uint64_t Address, raw_ostream &O);

  void printImm8(const MCInst *MI, unsigned OpNo, raw_ostream &O);
  void printImm16(const MCInst *MI, unsigned OpNo, raw_ostream &O);

  void printDirectMemOperand(const MCInst *MI, unsigned OpNo, raw_ostream &O);
  void printDirectIndexedOperand(const MCInst *MI, unsigned OpNo,
                                 raw_ostream &O);
  void printOperandDOI(const MCInst *MI, unsigned OpNo, raw_ostream &O);

  void printIndirectMemOperand(const MCInst *MI, unsigned OpNo,
                               raw_ostream &O) const;

  void printPCRelImm(const MCInst *MI, uint64_t Address, unsigned OpNo,
                     raw_ostream &O);
};

} // namespace llvm

#endif // LLVM_STM8_INST_PRINTER_H_INCLUDED
